function configure(config) {
  const { guildId, calendarId } = config;
  if (
    typeof guildId !== "string" ||
    !/^\d{17,20}$/.test(guildId) ||
    typeof calendarId !== "string" ||
    !calendarId ||
    calendarId.startsWith("YOUR_") ||
    /[/\\?#%\s]/.test(calendarId)
  ) {
    throw Error("Set a Discord server ID and a Google Calendar ID.");
  }
  return { guildId, collection: "/calendars/" + encodeURIComponent(calendarId) + "/events" };
}
const settings = { guildId: "YOUR_DISCORD_GUILD_ID", calendarId: "YOUR_GOOGLE_CALENDAR_ID" };
return [{ json: configure(settings) }];

function collect(items, config) {
  if (!Array.isArray(items)) throw Error("Discord returned an invalid scheduled event list.");
  const events = [],
    results = [],
    ids = new Set();
  for (const event of items) {
    const {
      id,
      guild_id,
      name,
      scheduled_start_time,
      scheduled_end_time,
      description,
      entity_metadata,
    } = event;
    if (
      typeof id !== "string" ||
      !/^\d{17,20}$/.test(id) ||
      guild_id !== config.guildId ||
      ids.has(id)
    ) {
      throw Error("Discord returned an invalid or mismatched event. No Calendar writes were made.");
    }
    ids.add(id);
    const start = Date.parse(scheduled_start_time),
      end = Date.parse(scheduled_end_time);
    if (
      typeof name !== "string" ||
      !name.trim() ||
      !/^\d{4}-\d\d-\d\dT.*(?:Z|[+-]\d\d:\d\d)$/.test(scheduled_start_time ?? "") ||
      !/^\d{4}-\d\d-\d\dT.*(?:Z|[+-]\d\d:\d\d)$/.test(scheduled_end_time ?? "") ||
      !Number.isFinite(start) ||
      !Number.isFinite(end) ||
      end <= start
    ) {
      results.push({ eventId: id, status: "invalid_event_time" });
      continue;
    }
    const location = entity_metadata?.location ?? "";
    if (typeof location !== "string" || (description != null && typeof description !== "string")) {
      results.push({ eventId: id, status: "invalid_event_details" });
      continue;
    }
    events.push({
      id,
      collection: config.collection,
      endpoint: config.collection + "/" + id,
      mapped: {
        summary: name,
        description: description ?? "",
        location,
        start: { dateTime: scheduled_start_time },
        end: { dateTime: scheduled_end_time },
      },
    });
  }
  return { events, results };
}
const reply = $input.first().json,
  config = $("Select the server and calendar").first().json;
if (reply.statusCode !== 200) throw Error("Discord did not return the scheduled event list.");
return collect(reply.body, config).events.map((event) => ({
  json: event,
  pairedItem: { item: 0 },
}));

function sameFields(saved, mapped) {
  return (
    saved.summary === mapped.summary &&
    (saved.description ?? "") === mapped.description &&
    (saved.location ?? "") === mapped.location &&
    Date.parse(saved.start?.dateTime) === Date.parse(mapped.start.dateTime) &&
    Date.parse(saved.end?.dateTime) === Date.parse(mapped.end.dateTime)
  );
}
function decide(event, status, body) {
  const fail = (value) => ({
    method: "",
    endpoint: "",
    tag: "",
    payload: {},
    result: { eventId: event.id, status: value },
  });
  const miss =
    status === 404 &&
    body?.error?.code === 404 &&
    (body.error.status === "NOT_FOUND" ||
      (Array.isArray(body.error.errors) &&
        body.error.errors.some((error) => error?.reason === "notFound")));
  if (miss)
    return {
      method: "POST",
      endpoint: event.collection,
      tag: "",
      payload: { id: event.id, ...event.mapped },
      result: {},
    };
  if (status !== 200 || body?.id !== event.id) return fail("lookup_unconfirmed");
  if (body.status === "cancelled") return fail("cancelled_target");
  if (sameFields(body, event.mapped)) return fail("unchanged");
  if (typeof body.etag !== "string" || !/^"[^"\r\n]+"$/.test(body.etag))
    return fail("etag_unconfirmed");
  return {
    method: "PATCH",
    endpoint: event.endpoint,
    tag: body.etag,
    payload: event.mapped,
    result: {},
  };
}
const event = $("Map the Discord events").item.json;
return {
  json: { event, ...decide(event, $json.statusCode, $json.body) },
  pairedItem: { item: $itemIndex },
};

function sameFields(saved, mapped) {
  return (
    saved.summary === mapped.summary &&
    (saved.description ?? "") === mapped.description &&
    (saved.location ?? "") === mapped.location &&
    Date.parse(saved.start?.dateTime) === Date.parse(mapped.start.dateTime) &&
    Date.parse(saved.end?.dateTime) === Date.parse(mapped.end.dateTime)
  );
}
function confirmed(event, method, status, body) {
  const ok =
    (status === 200 || (method === "POST" && status === 201)) &&
    body?.id === event.id &&
    sameFields(body, event.mapped);
  return {
    eventId: event.id,
    status: ok
      ? method === "POST"
        ? "created"
        : "updated"
      : status === 409 || status === 412
        ? "write_conflict"
        : "write_unconfirmed",
  };
}
const plan = $("Compare the Calendar event").item.json;
return {
  json: confirmed(plan.event, plan.method, $json.statusCode, $json.body),
  pairedItem: { item: $itemIndex },
};
